const projects = [
  { title: "Hesap Makinesi", tag: "js" },
  { title: "Kedi Galerisi", tag: "html" },
  { title: "Yıldız Oyunu", tag: "js" },
];

function renderProjects() {
  const box = document.querySelector("#projects");
  // temizle, her proje için article.card > h3 + p.tag
  box.textContent = "";
  for (const p of projects) {
    const card = document.createElement("article");
    card.classList.add("card");
    const title = document.createElement("h3");
    title.textContent = p.title;
    const tag = document.createElement("p");
    tag.classList.add("tag");
    tag.textContent = p.tag;
    card.append(title, tag);
    box.append(card);
  }
}

renderProjects();

check.js:
const cards = () => $$("#projects .card");
assert(cards().length === 3, "#projects içinde 3 kart (.card) olmalı.");
assert(cards().every((c) => c.tagName === "ARTICLE"), "Kartlar <article> olmalı.");
assert(cards().map((c) => c.querySelector("h3") && c.querySelector("h3").textContent.trim()).join(",") === "Hesap Makinesi,Kedi Galerisi,Yıldız Oyunu", "Her kartta proje adını yazan bir <h3> olmalı.");
assert(cards().every((c, i) => c.querySelector(".tag") && c.querySelector(".tag").textContent.trim() === projects[i].tag), "Her kartta etiketi yazan p.tag olmalı.");
projects.push({ title: "Blog", tag: "css" });
renderProjects();
assert(cards().length === 4 && cards()[3].querySelector("h3").textContent.trim() === "Blog", "Yeni proje ekleyip renderProjects() çağırınca 4 kart olmalı; önce temizlemeyi unutma.");

