const question = { text: "Kızıl gezegen hangisi?", options: ["Mars", "Venüs", "Merkür"], answer: 0 };
const feedback = document.querySelector("#feedback");

function renderOptions(q) {
  const box = document.querySelector("#options");
  // soruyu yaz, kutuyu temizle, her seçenek için düğme oluştur
  document.querySelector("#question").textContent = q.text;
  box.textContent = "";
  q.options.forEach((option, i) => {
    const btn = document.createElement("button");
    btn.classList.add("option");
    btn.textContent = option;
    btn.dataset.index = i;
    btn.addEventListener("click", () => {
      feedback.textContent = i === q.answer ? "Doğru!" : "Yanlış";
    });
    box.append(btn);
  });
}

renderOptions(question);

check.js:
const btns = () => $$("#options .option");
assert($("#question").textContent.trim() === "Kızıl gezegen hangisi?", "#question 'Kızıl gezegen hangisi?' olmalı.");
assert(btns().length === 3 && btns().map((b) => b.textContent.trim()).join(",") === "Mars,Venüs,Merkür", "#options içinde Mars, Venüs, Merkür yazan 3 .option düğmesi olmalı.");
assert(btns().every((b, i) => b.tagName === "BUTTON" && b.dataset.index === String(i)), "Her düğme <button> olmalı ve dataset.index'i sırası olmalı (0, 1, 2).");
click(btns()[2]);
assert($("#feedback").textContent.trim() === "Yanlış", "Yanlış seçeneğe tıklayınca #feedback 'Yanlış' olmalı.");
click(btns()[0]);
assert($("#feedback").textContent.trim() === "Doğru!", "Doğru seçeneğe tıklayınca #feedback 'Doğru!' olmalı.");
renderOptions({ text: "Halkalı gezegen?", options: ["Mars", "Venüs", "Merkür", "Satürn"], answer: 3 });
assert(btns().length === 4, "renderOptions önce kutuyu temizlemeli; 4 seçenekli soruda 4 düğme olmalı.");
assert($("#question").textContent.trim() === "Halkalı gezegen?", "#question yeni sorunun metnini göstermeli.");
click(btns()[3]);
assert($("#feedback").textContent.trim() === "Doğru!", "Doğru cevap q.answer'dan okunmalı.");
